console.log(extraction.data)                    // { vendor_name: 'Acme', total: 1500, ... }
console.log(extraction.confidence?.overall)     // 0.94
console.log(extraction.confidence?.fields)      // { vendor_name: 0.99, total: 0.91, ... }
